package org.owasp.webgoat.lessons.challenges.challenge7;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Random;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Demonstrates the FB.DMI_RANDOM_USED_ONLY_ONCE defect on line 18 of PasswordResetLink:
 * the Random is seeded with key.length() (a public value), making the admin reset link
 * fully predictable. An attacker who knows the key length can reproduce the exact same
 * scrambled output.
 */
class PasswordResetLinkTest {

  @Test
  @DisplayName("Admin reset link is predictable from the seed (key.length)")
  void adminResetLinkIsPredictableFromSeed() {
    String username = "admin";
    String key = "webgoat"; // length 7

    // Reproduce the exact same computation the method does, using the same seed
    Random random = new Random();
    random.setSeed(key.length()); // line 18: seed is key.length() = 7
    String md5 = MD5.getHashString(username);
    String expected =
        PasswordResetLink.scramble(
            random,
            PasswordResetLink.scramble(random, PasswordResetLink.scramble(random, md5)));

    // The actual method should produce the same result because it uses the same seed
    String actual = new PasswordResetLink().createPasswordReset(username, key);

    assertThat(actual).isEqualTo(expected);
  }

  @Test
  @DisplayName("Admin reset link is deterministic across calls with same key length")
  void adminResetLinkIsDeterministic() {
    PasswordResetLink linkGenerator = new PasswordResetLink();
    String link1 = linkGenerator.createPasswordReset("admin", "webgoat");
    String link2 = linkGenerator.createPasswordReset("admin", "webgoat");
    assertThat(link1).isEqualTo(link2);
  }
