package org.owasp.webgoat.lessons.challenges.challenge7;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Random;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Tests for the FB.DMI_RANDOM_USED_ONLY_ONCE defect on line 18 of PasswordResetLink:
 * the Random is seeded with key.length() (a public value), making the admin reset link
 * fully predictable. The fix should make the output unpredictable.
 */
class PasswordResetLinkTest {

  @Test
  @DisplayName("Admin reset link must NOT be predictable from key length")
  void adminResetLinkMustNotBePredictableFromKeyLength() {
    String username = "admin";
    String key = "webgoat"; // length 7

    // Compute what the output WOULD be if the seed were key.length() (the buggy behavior)
    Random predictableRandom = new Random();
    predictableRandom.setSeed(key.length());
    String md5 = MD5.getHashString(username);
    String predictedOutput =
        PasswordResetLink.scramble(
            predictableRandom,
            PasswordResetLink.scramble(predictableRandom, PasswordResetLink.scramble(predictableRandom, md5)));

    // The actual output should NOT match the predictable output
    // (i.e., the seed should not be derived from a public value like key.length())
    String actualOutput = new PasswordResetLink().createPasswordReset(username, key);

    assertThat(actualOutput)
        .as("Admin reset link should not be predictable from key.length()")
        .isNotEqualTo(predictedOutput);
  }
