  private static String toHex(byte hash[]) {
    StringBuilder buf = new StringBuilder(hash.length * 2);
    for (byte element : hash) {
      int intVal = element & 0xff;
      if (intVal < 0x10) {
        // append a zero before a one digit hex
        // number to make it two digits.
        buf.append("0");
